-- migration files -- the restored functions are byte-identical to what those migrations installed).
--
-- Order: roll the APPLICATION back first (the pre-M5 app does not call any M5 function).
-- Refuses while: an exception alert is being sent, an exception is 'acknowledged' (the pre-M5 status check has no such
-- state -- resolve or reopen it first), a box-office terminal hold is still active, or competition desk payments were
-- recorded through the M5 function (their audit rows would be lost -- export them first).
-- Data NOT preserved: exception classification/alert/acknowledgement columns, the exception audit trail, reconcile
-- backoff counters, payment_exception in-app notifications (deleted so the original type CHECK can be restored).

begin;

do $$
begin
  if exists (select 1 from public.event_order_settlement_exceptions where alert_status in ('pending', 'processing') and status <> 'resolved') then
    raise exception 'paywh1a rollback refused: payment exception alerts are still queued (let the cron deliver them first)';
  end if;
  if exists (select 1 from public.event_order_settlement_exceptions where status = 'acknowledged') then
    raise exception 'paywh1a rollback refused: acknowledged exceptions exist (resolve them first)';
  end if;
  if exists (select 1 from public.event_registrations where terminal_hold_until > now()) then
    raise exception 'paywh1a rollback refused: active box-office terminal holds exist';
  end if;
  if exists (select 1 from public.event_competition_checkin_payment_audit) then
    raise exception 'paywh1a rollback refused: competition desk payment audit rows exist (export them first)';
  end if;
end $$;

